sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
uniform float threshold;
layout(color) uniform half4 color;
uniform float blend;
uniform float alpha;
float luma(float3 c) { return dot(c, float3(0.2126, 0.7152, 0.0722)); }
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (src.a <= 0.0) return src;
    half4 b = blurred.eval(coord);
    float lb = b.a > 0.0 ? luma(float3(b.rgb) / float(b.a)) : 1.0;
    float dark = clamp((threshold - lb) / max(threshold, 0.001), 0.0, 1.0) * clamp(float(b.a), 0.0, 1.0);
    float3 base = float3(src.rgb) / float(src.a);
    float3 shade = mix(base * float3(color.rgb), float3(color.rgb), 1.0 - clamp(blend, 0.0, 1.0));
    float3 rgb = mix(base, shade, dark * clamp(alpha, 0.0, 1.0));
    return half4(half3(rgb) * src.a, src.a);
}
